,p_display_sequence=>10
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(10801889137000846)
,p_plugin_id=>wwv_flow_imp.id(10801551217000846)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_static_id=>'ALLOW_SHARING'
,p_prompt=>'Allow Sharing'
,p_apexlang_name=>'allowSharing'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'N'
,p_is_translatable=>false
